def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(size, separators):
        out = []
        start = 0
        for pos in separators:
            if start < pos:
                out.append((start, pos))
            start = pos + 1
        if start < size:
            out.append((start, size))
        return out

    row_blocks = segments(h, sep_rows)
    col_blocks = segments(w, sep_cols)

    nonsep = [
        grid[r][c]
        for r in range(h) if r not in sep_rows
        for c in range(w) if c not in sep_cols
    ]
    background = max(set(nonsep), key=nonsep.count)

    result = []
    for r0, r1 in row_blocks:
        row = []
        for c0, c1 in col_blocks:
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if count >= 2 else background)
        result.append(row)
    return result
